struct Rule { ExprPtr (*nud)(Parser&); ExprPtr (*led)(Parser&, ExprPtr); int lbp; };
static const std::array<Rule, TokCount> kRules = {{
  /* Minus   */ {nud_prefix,  led_binary, 30},
  /* LParen  */ {nud_group,   led_call,   60},
  /* Literal */ {nud_literal, nullptr,     0},
}};
ExprPtr Parser::parseExpr(int minBp) {
  auto left = kRules[idx(peek())].nud(*this);            // null denotation
  while (minBp < kRules[idx(peek())].lbp)                // left denotation
    left = kRules[idx(consume())].led(*this, std::move(left));
  return left;
}
